package com.routeplanner;

import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.RuneLite;

public class RoutePlannerTest {
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(RoutePlannerPlugin.class);
        RuneLite.main(args);
    }
}

package com.routeplanner;

import com.routeplanner.model.RouteStep;
import com.routeplanner.model.StepType;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.swing.*;

@Slf4j
public class TileMenuHandler {

    private static final String ADD_LOCATION_STEP = "Add Location Step";
    private static final String SET_TRANSITION_POINT = "Set Transition Point";
    private static final String SET_TRANSITION_OBJECT = "Set Transition Object";
    private static final String ADD_TO_ITEM_STEP = "Add to Item Step";
    private static final String CREATE_ITEM_STEP = "Create Item Step";
    private static final String CLEAR_SELECTION = "Clear Item Selection";
    private static final String MENU_TARGET = "Route Planner";
    // Shop stock container widget: group 300, child 16
    private static final int SHOP_STOCK_WIDGET_ID = (300 << 16) | 16;

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final net.runelite.client.game.ItemManager itemManager;

    // Items collected via shift+right-click in shops, pending bundling into one step
    private final java.util.List<String> pendingShopItems = new java.util.ArrayList<>();
    // Item name under the cursor when the menu was opened
    private String lastRightClickedShopItem = null;

    @Inject
    public TileMenuHandler(Client client, RoutePlannerPlugin plugin,
                           net.runelite.client.game.ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
    }

    public void startUp() {
    }

    public void shutDown() {
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (plugin.getActiveRoute() == null) return;
        com.routeplanner.model.RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return;
        if (step.getSkillingTargetNpc() == null) return;

        net.runelite.api.MenuEntry entry = event.getMenuEntry();
        if (!(entry.getActor() instanceof NPC)) return;
        NPC npc = (NPC) entry.getActor();
        if (npc.getName() == null) return;

        String npcName = npc.getName();
        String targetName = step.getSkillingTargetNpc();
        boolean nameMatch = npcName.equalsIgnoreCase(targetName)
            || npcName.toLowerCase().startsWith(targetName.toLowerCase() + " ")
            || npcName.toLowerCase().startsWith(targetName.toLowerCase() + "(");
        if (!nameMatch) return;

        String option = entry.getOption();
        // Deprioritize everything except Pickpocket and Examine
        if (option.equalsIgnoreCase("Pickpocket")) {
            entry.setDeprioritized(false);
        } else if (!option.equalsIgnoreCase("Examine") && !option.equalsIgnoreCase("Cancel")) {
            entry.setDeprioritized(true);
        }
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        if (plugin.getActiveRoute() == null) return;

        boolean hasWalkHere = false;
        for (MenuEntry entry : event.getMenuEntries()) {
            if (entry.getOption().equals("Walk here")) hasWalkHere = true;
        }

        if (hasWalkHere && client.isKeyPressed(KeyCode.KC_SHIFT)) {
            client.createMenuEntry(-1)
                .setOption(ADD_LOCATION_STEP)
                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                .setType(MenuAction.RUNELITE)
                .setDeprioritized(false);
            if (plugin.getActiveRoute() != null && plugin.getActiveRoute().getActiveStep() != null) {
                client.createMenuEntry(-1)
                    .setOption(SET_TRANSITION_POINT)
                    .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                    .setType(MenuAction.RUNELITE)
                    .setDeprioritized(false);
                // Also offer object ID grab if a game object is under the cursor
                net.runelite.api.Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
                if (tile != null) {
                    for (net.runelite.api.GameObject obj : tile.getGameObjects()) {
                        if (obj != null) {
                            client.createMenuEntry(-1)
                                .setOption(SET_TRANSITION_OBJECT + " (ID:" + obj.getId() + ")")
                                .setTarget("<col=00ff00>" + MENU_TARGET + "</col>")
                                .setType(MenuAction.RUNELITE)
                                .setDeprioritized(false);
                            break;
                        }
                    }
                }
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        String opt = event.getMenuOption();

        // Add to Item Step uses the item name as target, not MENU_TARGET
        if (opt.equals(ADD_TO_ITEM_STEP)) {
            if (lastRightClickedShopItem != null
                    && !pendingShopItems.contains(lastRightClickedShopItem)) {
                pendingShopItems.add(lastRightClickedShopItem);
                client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                    "<col=00ff00>Route Planner:</col> added " + lastRightClickedShopItem
                    + " (" + pendingShopItems.size() + " selected)", null);
            }
            event.consume();
            return;
        }

        if (!event.getMenuTarget().contains(MENU_TARGET)) return;

        if (opt.startsWith(SET_TRANSITION_OBJECT)) {
            com.routeplanner.model.RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            net.runelite.api.Tile tile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (tile == null) return;
            for (net.runelite.api.GameObject obj : tile.getGameObjects()) {
                if (obj != null) {
                    activeStep.setTransitionObjectId(obj.getId());
                    plugin.saveRoutes();
                    client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                        "<col=00ff00>Route Planner:</col> transition object ID set to " + obj.getId(), null);
                    log.info("Transition object ID set to {}", obj.getId());
                    break;
                }
            }
        } else if (opt.equals(SET_TRANSITION_POINT)) {
            net.runelite.api.Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) return;
            com.routeplanner.model.RouteStep activeStep = plugin.getActiveRoute() == null ? null
                : plugin.getActiveRoute().getActiveStep();
            if (activeStep == null) return;
            net.runelite.api.coords.WorldPoint raw = selectedTile.getWorldLocation();
            activeStep.setTransitionPoint(raw);
            plugin.saveRoutes();
            client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                "<col=00ff00>Route Planner:</col> transition point set to " + raw, null);
            log.info("Transition point set to {}", raw);
        } else if (opt.equals(ADD_LOCATION_STEP)) {
            net.runelite.api.Tile selectedTile = client.getTopLevelWorldView().getSelectedSceneTile();
            if (selectedTile == null) {
                log.warn("Route Planner: no selected tile found");
                return;
            }
            promptAddLocationStep(selectedTile.getWorldLocation());
        } else if (opt.startsWith(CREATE_ITEM_STEP)) {
            createItemStepFromSelection();
            event.consume();
        } else if (opt.equals(CLEAR_SELECTION)) {
            pendingShopItems.clear();
            client.addChatMessage(net.runelite.api.ChatMessageType.GAMEMESSAGE, "",
                "<col=ff5555>Route Planner:</col> item selection cleared", null);
            event.consume();
        }
    }

    private void createItemStepFromSelection() {
        if (pendingShopItems.isEmpty() || plugin.getActiveRoute() == null) return;
        final java.util.List<String> snapshot = new java.util.ArrayList<>(pendingShopItems);
        pendingShopItems.clear();
        SwingUtilities.invokeLater(() -> {
            String itemList = String.join(", ", snapshot);
            String firstName = snapshot.get(0);
            String stepName = "Buy: " + firstName
                + (snapshot.size() > 1 ? " +" + (snapshot.size() - 1) + " more" : "");
            RouteStep step = new RouteStep(stepName, StepType.ITEM, null, -1);
            step.setItemList(itemList);
            step.setItemMode("SHOP");
            plugin.addStep(plugin.getActiveRoute(), step);
            log.info("Created shop item step with {} items: {}", snapshot.size(), itemList);
        });
    }

    private void promptAddLocationStep(WorldPoint tile) {
        SwingUtilities.invokeLater(() -> {
            if (plugin.getActiveRoute() == null) {
                JOptionPane.showMessageDialog(null, "Select or create a route first.");
                return;
            }
            new StepEditorDialog(plugin, plugin.getActiveRoute(), null, tile).setVisible(true);
            log.info("Opened step editor seeded at {}", tile);
        });
    }
}

package com.routeplanner.hub;

import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;

/**
 * Read-only GETs against the Route Hub's GitHub-hosted catalog. Every call is a plain HTTP GET to
 * raw.githubusercontent.com -- nothing is ever uploaded or posted. Bounds (payload size caps) are
 * enforced here so a malformed or oversized response can never wedge the panel; callers get a
 * {@link HubFetchException} instead of a crash, with a message safe to show the user directly.
 */
@Slf4j
@Singleton
public class RouteHubFetcher {

    /** Base raw-content URL for the curated routes repo, branch pinned to avoid surprise changes. */
    private static final String BASE_URL =
        "https://raw.githubusercontent.com/BlackDeath-Osrs/route-planner-routes/main/";

    // Sanity caps mirroring the v1.4 plan bounds. A response over these is rejected outright.
    private static final long MAX_INDEX_BYTES = 1_500_000;   // ~1 MB catalog, some headroom
    private static final long MAX_ROUTE_BYTES = 2_500_000;   // ~2 MB per-route cap, some headroom
    private static final long MAX_ICON_BYTES = 25_000;       // 20 KB icon cap, some headroom

    private final OkHttpClient okHttpClient;

    @Inject
    public RouteHubFetcher(OkHttpClient okHttpClient) {
        this.okHttpClient = okHttpClient;
    }

    /** Fetches index.json as raw text. Caller is responsible for JSON parsing + schema validation. */
    public String fetchIndex() throws HubFetchException {
        return fetchText("index.json", MAX_INDEX_BYTES, "route catalog");
    }

    /** Fetches a single route file (path as given in index.json's "file" field) as raw text. */
    public String fetchRoute(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchText(relativePath, MAX_ROUTE_BYTES, "route");
    }

    /** Fetches an icon (path as given in index.json's "icon" field) as raw bytes. */
    public byte[] fetchIcon(String relativePath) throws HubFetchException {
        requireSafeRelativePath(relativePath);
        return fetchBytes(relativePath, MAX_ICON_BYTES, "icon");
    }

    // ---- internals ----

    /**
     * index.json and route "file"/"icon" entries are relative paths we build a URL from. Reject
     * anything that looks like it is trying to escape the repo (".." segments) or specify a whole
     * new host (a scheme or a leading "//") -- the catalog must only ever point within itself.
     */
    private void requireSafeRelativePath(String relativePath) throws HubFetchException {
        if (relativePath == null || relativePath.isEmpty()
            || relativePath.contains("..")
            || relativePath.startsWith("/")
            || relativePath.contains("://")) {
            throw new HubFetchException("The Route Hub catalog referenced an invalid file path.");
        }
    }

    private String fetchText(String relativePath, long maxBytes, String what) throws HubFetchException {
        byte[] bytes = fetchBytes(relativePath, maxBytes, what);
        return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    }

    private byte[] fetchBytes(String relativePath, long maxBytes, String what) throws HubFetchException {
        Request request = new Request.Builder().url(BASE_URL + relativePath).build();
        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new HubFetchException("Couldn't reach the Route Hub (the " + what + " wasn't found or the server had an error).");
            }
            if (response.body() == null) {
                throw new HubFetchException("The Route Hub sent back an empty response for the " + what + ".");
            }
            long declaredLength = response.body().contentLength();
            if (declaredLength > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            byte[] data = response.body().bytes();
            if (data.length > maxBytes) {
                throw new HubFetchException("The " + what + " from the Route Hub was too large to load safely.");
            }
            return data;
        } catch (IOException e) {
            log.warn("Route Hub fetch failed for {}", relativePath, e);
            throw new HubFetchException("Couldn't connect to the Route Hub. Check your connection and try again.");
        }
    }
}

package com.routeplanner.hub;

import java.util.List;

/**
 * One catalog entry from index.json. All fields are read-only data from the network -- nothing
 * here is trusted until it has passed {@link HubRouteEntry#validate()}, which enforces the v1.4
 * plan's bounds (name/description length, step count) and re-runs the link scanner over every
 * free-text field, independently of whatever checks the submitter's editor may or may not have
 * applied.
 */
public class HubRouteEntry {
    public String id;
    public String name;
    public String author;
    public String description;
    public String icon;
    public String file;
    public int steps;
    public List<String> tags;
    public String updated;

    private static final int MAX_NAME_LEN = 100;
    private static final int MAX_DESC_LEN = 120;
    private static final int MAX_STEPS = 1500;

    /**
     * @return null if the entry is safe to display/install, or a short reason if it should be
     * rejected. Never throws -- a malformed catalog entry should be skipped, not crash the panel.
     */
    public String validate() {
        if (id == null || id.isEmpty()) return "missing id";
        if (id.contains("..") || id.contains("/") || id.contains("\\")) return "unsafe id";
        if (name == null || name.isEmpty()) return "missing name";
        if (name.length() > MAX_NAME_LEN) return "name too long";
        if (author == null || author.isEmpty()) return "missing author";
        if (description == null) return "missing description";
        if (description.length() > MAX_DESC_LEN) return "description too long";
        if (file == null || file.isEmpty() || file.contains("..") || file.startsWith("/")) return "unsafe file path";
        if (icon != null && (icon.contains("..") || icon.startsWith("/"))) return "unsafe icon path";
        if (steps < 0 || steps > MAX_STEPS) return "step count out of bounds";

        String linkErr = com.routeplanner.util.RouteTextValidator.checkField("Route name", name);
        if (linkErr == null) linkErr = com.routeplanner.util.RouteTextValidator.checkField("Description", description);
        if (linkErr == null && author != null) linkErr = com.routeplanner.util.RouteTextValidator.checkField("Author", author);
        if (linkErr != null) return linkErr;

        return null;
    }
}

package com.routeplanner.hub;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.ui.ColorScheme;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/**
 * The Route Hub browse view. Skeleton for now (v1.4 step 4b): fetches the catalog and lists
 * routes as plain rows. No icons, search, tabs, or the warning banner yet -- those come once this
 * fetch-parse-render path is proven against the live repo. Network work runs off the EDT via
 * SwingWorker; nothing here ever blocks the UI thread.
 */
@Slf4j
public class RouteHubPanel extends JPanel {

    private final com.routeplanner.RoutePlannerPlugin plugin;
    private final RouteHubCatalog catalog;
    private final Runnable onBack;
    private final JPanel listPanel;
    private final JLabel statusLabel;
    private boolean loadedOnce = false;
    private JLabel footerLabel;

    public RouteHubPanel(com.routeplanner.RoutePlannerPlugin plugin, RouteHubCatalog catalog, Runnable onBack) {
        this.plugin = plugin;
        this.catalog = catalog;
        this.onBack = onBack;

        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(8, 8, 8, 8));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JButton back = new JButton("\u2039 Back");
        back.setForeground(new Color(255, 152, 31));
        back.setBorderPainted(false);
        back.setContentAreaFilled(false);
        back.setFocusPainted(false);
        back.setCursor(new Cursor(Cursor.HAND_CURSOR));
        back.addActionListener(e -> onBack.run());

        JLabel title = new JLabel("Route Hub");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.add(back, BorderLayout.WEST);
        header.add(title, BorderLayout.CENTER);

        JPanel topStack = new JPanel();
        topStack.setLayout(new BoxLayout(topStack, BoxLayout.Y_AXIS));
        topStack.setOpaque(false);
        JTextField search = new JTextField();
        search.setBackground(ColorScheme.DARK_GRAY_COLOR.brighter());
        search.setForeground(Color.WHITE);
        search.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(60, 60, 60), 1),
            new EmptyBorder(5, 7, 5, 7)));
        search.putClientProperty("JTextField.placeholderText", "Search routes\u2026");
        search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            public void insertUpdate(javax.swing.event.DocumentEvent e) { applyFilter(search.getText()); }
            public void removeUpdate(javax.swing.event.DocumentEvent e) { applyFilter(search.getText()); }
            public void changedUpdate(javax.swing.event.DocumentEvent e) { applyFilter(search.getText()); }
        });
        JPanel searchWrap = new JPanel(new BorderLayout());
        searchWrap.setOpaque(false);
        searchWrap.setBorder(new EmptyBorder(6, 0, 0, 0));
        searchWrap.add(search, BorderLayout.CENTER);

        topStack.add(header);
        topStack.add(searchWrap);
        add(topStack, BorderLayout.NORTH);

        statusLabel = new JLabel("Loading\u2026");
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setBorder(new EmptyBorder(10, 4, 10, 4));

        listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listPanel.add(statusLabel);

        JScrollPane scroll = new JScrollPane(listPanel);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getVerticalScrollBar().setUnitIncrement(12);
        add(scroll, BorderLayout.CENTER);

        footerLabel = new JLabel(" ");
        footerLabel.setForeground(Color.WHITE);
        footerLabel.setFont(footerLabel.getFont().deriveFont(9.5f));
        footerLabel.setBorder(new EmptyBorder(6, 2, 2, 2));
        footerLabel.setHorizontalAlignment(SwingConstants.CENTER);
        footerLabel.setToolTipText("The date the Route Hub catalog was last changed \u2014 "
            + "not necessarily this specific route.");

        JPanel bottomStack = new JPanel();
        bottomStack.setLayout(new BoxLayout(bottomStack, BoxLayout.Y_AXIS));
        bottomStack.setOpaque(false);
        bottomStack.add(footerLabel);
        bottomStack.add(buildWarningBanner());
        add(bottomStack, BorderLayout.SOUTH);
    }

    /** Called each time the Hub view is switched to. Loads once per panel lifetime for now --
     *  a manual refresh / re-check-on-open comes with the Installed tab in a later step. */
    public void onShown() {
        if (loadedOnce) return;
        loadedOnce = true;
        load();
    }

    // Decoded icons keyed by entry id, so re-rendering the list (e.g. after a tab switch) does not
    // re-fetch or re-decode icons that already loaded successfully this session. Cleared never --
    // the panel's lifetime is one Hub-view visit, and 12-48px icons are cheap to hold in memory.
    private final java.util.Map<String, ImageIcon> iconCache = new java.util.HashMap<>();
    private java.util.List<HubRouteEntry> allEntries = java.util.Collections.emptyList();

    /** Fetches and decodes one entry's icon off the EDT, then swaps it into the given label. Never
     *  throws back to the caller and never leaves the label in a broken state -- on any failure the
     *  grey-blue placeholder simply stays as-is. */
    private void loadIconInto(JLabel target, HubRouteEntry entry) {
        ImageIcon cached = iconCache.get(entry.id);
        if (cached != null) {
            target.setIcon(cached);
            return;
        }
        if (entry.icon == null || entry.icon.isEmpty()) return;

        new SwingWorker<ImageIcon, Void>() {
            @Override
            protected ImageIcon doInBackground() {
                try {
                    byte[] bytes = catalog.fetchIconBytes(entry.icon);
                    java.awt.Image img = javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));
                    if (img == null) return null; // not a decodable image
                    if (img.getWidth(null) <= 0 || img.getHeight(null) <= 0) return null;
                    java.awt.Image scaled = img.getScaledInstance(48, 48, java.awt.Image.SCALE_SMOOTH);
                    return new ImageIcon(scaled);
                } catch (Exception e) {
                    log.debug("Icon load failed for {}: {}", entry.id, e.toString());
                    return null;
                }
            }

            @Override
            protected void done() {
                try {
                    ImageIcon icon = get();
                    if (icon == null) return; // leave the placeholder as-is
                    iconCache.put(entry.id, icon);
                    target.setIcon(icon);
                } catch (Exception e) {
                    // failed or cancelled -- placeholder remains, nothing to show the user for this
                }
            }
        }.execute();
    }

    private static final int MAX_STEPS = 1500;
    private static final int MAX_NOTE_LEN = 280;
    private static final int MAX_NAME_LEN = 100;

    /**
     * Re-validates every free-text field of every step in a fetched route, independently of
     * whatever the catalog entry or PR review already checked. A route JSON fetched over the
     * network must never be trusted just because it appeared in the curated index -- this is the
     * import-time re-validation layer from the security model. Returns null if the route is safe
     * to install, or a short user-facing reason if it should be refused.
     */
    private String validateFetchedRoute(com.routeplanner.model.Route route) {
        if (route == null || route.getName() == null) return "The route file is empty or malformed.";
        if (route.getName().length() > MAX_NAME_LEN) return "The route's name is too long.";

        String nameErr = com.routeplanner.util.RouteTextValidator.checkField("Route name", route.getName());
        if (nameErr != null) return nameErr;

        int totalSteps = 0;
        java.util.List<com.routeplanner.model.RouteSection> sections = route.getSections();
        if (sections == null) return null; // an empty route is unusual but not unsafe

        for (com.routeplanner.model.RouteSection section : sections) {
            if (section == null || section.getSteps() == null) continue;

            String secErr = com.routeplanner.util.RouteTextValidator.checkField("Section name", section.getName());
            if (secErr != null) return secErr;

            for (com.routeplanner.model.RouteStep step : section.getSteps()) {
                if (step == null) continue;
                totalSteps++;
                if (totalSteps > MAX_STEPS) return "This route has too many steps.";

                if (step.getName() != null && step.getName().length() > MAX_NAME_LEN) {
                    return "A step name is too long.";
                }
                if (step.getNoteText() != null && step.getNoteText().length() > MAX_NOTE_LEN) {
                    return "A step's note is too long.";
                }

                String err = com.routeplanner.util.RouteTextValidator.checkField("Step name", step.getName());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Note", step.getNoteText());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Highlight NPC", step.getNpcHighlight());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Dialogue options", step.getDialogOptions());
                if (err == null) err = com.routeplanner.util.RouteTextValidator.checkField("Items", step.getItemList());
                if (err != null) return err;
            }
        }
        return null;
    }

    private void load() {
        new SwingWorker<List<HubRouteEntry>, Void>() {
            private HubFetchException failure;

            @Override
            protected List<HubRouteEntry> doInBackground() {
                try {
                    return catalog.loadValidEntries();
                } catch (HubFetchException e) {
                    failure = e;
                    return null;
                }
            }

            @Override
            protected void done() {
                listPanel.remove(statusLabel);
                if (failure != null) {
                    showMessage(failure.getMessage());
                    return;
                }
                List<HubRouteEntry> entries;
                try {
                    entries = get();
                } catch (Exception e) {
                    showMessage("Something went wrong loading the Route Hub.");
                    return;
                }
                if (entries == null || entries.isEmpty()) {
                    showMessage("No routes are available yet.");
                    return;
                }
                allEntries = entries;
                applyFilter("");
                updateFooter(entries);
            }
        }.execute();
    }

    /** Re-renders the list from allEntries, keeping only rows whose name, description, author, or
     *  tags contain the query (case-insensitive). Rebuilding rows from scratch each time is simpler
     *  and less error-prone than trying to show/hide already-built components, and with a catalog
     *  this small the cost is negligible. */
    private void applyFilter(String query) {
        listPanel.removeAll();
        String q = query == null ? "" : query.trim().toLowerCase();

        java.util.List<HubRouteEntry> matches = new java.util.ArrayList<>();
        for (HubRouteEntry entry : allEntries) {
            if (q.isEmpty() || matchesQuery(entry, q)) matches.add(entry);
        }

        if (matches.isEmpty()) {
            showMessage(q.isEmpty() ? "No routes are available yet." : "No routes match \"" + query + "\".");
        } else {
            for (HubRouteEntry entry : matches) {
                listPanel.add(buildRow(entry));
                listPanel.add(Box.createVerticalStrut(6));
            }
        }
        listPanel.revalidate();
        listPanel.repaint();
    }

    private boolean matchesQuery(HubRouteEntry entry, String lowerQuery) {
        if (entry.name != null && entry.name.toLowerCase().contains(lowerQuery)) return true;
        if (entry.description != null && entry.description.toLowerCase().contains(lowerQuery)) return true;
        if (entry.author != null && entry.author.toLowerCase().contains(lowerQuery)) return true;
        if (entry.tags != null) {
            for (String tag : entry.tags) {
                if (tag != null && tag.toLowerCase().contains(lowerQuery)) return true;
            }
        }
        return false;
    }

    /** Shows the most recent "updated" date across the catalog, in a small footer. A single line
     *  for the whole Hub, not per-row, since the ask was catalog freshness at a glance. */
    private void updateFooter(java.util.List<HubRouteEntry> entries) {
        String latest = null;
        for (HubRouteEntry entry : entries) {
            if (entry.updated == null || entry.updated.isEmpty()) continue;
            if (latest == null || entry.updated.compareTo(latest) > 0) latest = entry.updated;
        }
        footerLabel.setText(latest != null ? "Route Hub last updated " + latest : " ");
    }

    private void showMessage(String text) {
        JLabel msg = new JLabel(text);
        msg.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        msg.setBorder(new EmptyBorder(10, 4, 10, 4));
        listPanel.add(msg);
        listPanel.revalidate();
        listPanel.repaint();
    }

    /** A route row: a 48x48 icon placeholder on the left, name/description/author line in the
     *  middle, and a small green "+" install control anchored to the bottom-right of the sub-line.
     *  Real icon bytes and real install behaviour arrive with the install step (4e/4f); this gets
     *  the layout and sizing right first, since that is what is actually visible right now. */
    /** The persistent "Community content" disclosure: expanded by default, collapsible to a single
     *  line via the chevron, with the choice remembered across sessions. This replaces a per-install
     *  confirmation dialog -- the caution is visible the whole time the Hub is being browsed, rather
     *  than a click-through box shown once per install. */
    private JPanel buildWarningBanner() {
        JPanel banner = new JPanel(new BorderLayout());
        banner.setBackground(new Color(42, 36, 22));
        banner.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(90, 74, 31), 1),
            new EmptyBorder(0, 0, 0, 0)));

        JLabel label = new JLabel("\u26a0 Community content");
        label.setForeground(new Color(255, 204, 102));
        label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
        label.setBorder(new EmptyBorder(8, 10, 8, 4));

        JLabel chevron = new JLabel();
        chevron.setForeground(new Color(216, 201, 143));
        chevron.setFont(chevron.getFont().deriveFont(11f));
        chevron.setBorder(new EmptyBorder(8, 4, 8, 10));
        chevron.setCursor(new Cursor(Cursor.HAND_CURSOR));

        JPanel head = new JPanel(new BorderLayout());
        head.setOpaque(false);
        head.add(label, BorderLayout.WEST);
        head.add(chevron, BorderLayout.EAST);
        head.setCursor(new Cursor(Cursor.HAND_CURSOR));

        String warningText = "These routes are made by other players, not by Route Planner. "
            + "Submissions are reviewed and links are blocked, but always be cautious \u2014 never "
            + "follow a step that asks you to visit a website, share your account, or do anything "
            + "outside the game.";

        JLabel body = new JLabel("<html><div style=\'width:180px;\'>" + warningText + "</div></html>");
        body.setForeground(new Color(216, 201, 143));
        body.setFont(body.getFont().deriveFont(10.5f));
        body.setBorder(new EmptyBorder(0, 10, 10, 10));

        // The panel text is small to fit the row width; the tooltip shows the same words at normal
        // system tooltip size/font, which is easier to read on request.
        String tooltipHtml = "<html><div style=\'width:220px;\'>" + warningText + "</div></html>";
        body.setToolTipText(tooltipHtml);
        label.setToolTipText(tooltipHtml);

        banner.add(head, BorderLayout.NORTH);
        banner.add(body, BorderLayout.CENTER);

        Runnable applyState = () -> {
            boolean collapsed = plugin.isHubWarningCollapsed();
            body.setVisible(!collapsed);
            chevron.setText(collapsed ? "\u25b8" : "\u25be");
        };
        applyState.run();

        java.awt.event.MouseAdapter toggle = new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                plugin.setHubWarningCollapsed(!plugin.isHubWarningCollapsed());
                applyState.run();
                banner.revalidate();
                banner.repaint();
            }
        };
        head.addMouseListener(toggle);
