package com.routeplanner.model;

import com.google.gson.annotations.SerializedName;
import lombok.Data;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.Predicate;

@Data
public class Route {
    private String name;
    private List<RouteSection> sections = new ArrayList<>();

    /** Set only when this route was installed from the Route Hub; holds the hub catalog's entry id.
     *  Null for manually created or file-imported routes. This is how the browse panel knows a route
     *  is already installed (and can offer Remove instead of Install) without a second, separate
     *  persisted set that could drift out of sync with the real route list. */
    private String hubSourceId;
    private boolean repeatable = false; // if true, resets and restarts when last step completes

    // Legacy flat-step format; migrated into a default section on load.
    @SerializedName("steps")
    private List<RouteStep> legacySteps;

    public Route(String name) {
        this.name = name;
    }

    public List<RouteStep> getAllSteps() {
        List<RouteStep> all = new ArrayList<>();
        if (sections != null) {
            for (RouteSection sec : sections) {
                if (sec.getSteps() != null) all.addAll(sec.getSteps());
            }
        }
        return all;
    }

    /** Flattened read accessor used across the codebase. */
    public List<RouteStep> getSteps() {
        return getAllSteps();
    }

    public void migrateIfNeeded() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty() && legacySteps != null && !legacySteps.isEmpty()) {
            RouteSection def = new RouteSection(UUID.randomUUID().toString(), "Steps");
            def.getSteps().addAll(legacySteps);
            sections.add(def);
        }
        legacySteps = null;
        // v1.2: old agility steps (StepType.AGILITY, now removed) deserialize with type==null.
        // Convert them to the new skilling form (skill=AGILITY) + course start location.
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep st : sec.getSteps()) {
                if (st.getType() == null && st.getAgilityCourse() != null) {
                    st.setType(StepType.SKILLING);
                    st.setSkillingSkill("AGILITY");
                    st.setSkillingGoalType(st.getAgilityGoalType() != null ? st.getAgilityGoalType() : "LEVEL");
                    st.setSkillingGoalValue(st.getAgilityGoalValue());
                    net.runelite.api.coords.WorldPoint loc =
                        com.routeplanner.agility.AgilityCoursePresets.startLocation(st.getAgilityCourse());
                    if (loc != null && st.getWorldPoint() == null) st.setWorldPoint(loc);
                    if (st.getName() == null || st.getName().isEmpty()) {
                        st.setName("Agility: " + st.getAgilityCourse());
                    }
                }
            }
        }
    }

    public RouteSection findSection(String id) {
        if (id == null || sections == null) return null;
        for (RouteSection s : sections) if (id.equals(s.getId())) return s;
        return null;
    }

    public RouteSection ensureLastSection() {
        if (sections == null) sections = new ArrayList<>();
        if (sections.isEmpty()) {
            sections.add(new RouteSection(UUID.randomUUID().toString(), "Section 1"));
        }
        return sections.get(sections.size() - 1);
    }

    public void addStepToSection(RouteStep step, String sectionId) {
        RouteSection sec = findSection(sectionId);
        if (sec == null) sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void addStepToLastSection(RouteStep step) {
        RouteSection sec = ensureLastSection();
        step.setSectionId(sec.getId());
        sec.getSteps().add(step);
    }

    public void removeStep(RouteStep step) {
        if (sections == null) return;
        for (RouteSection sec : sections) {
            if (sec.getSteps() != null && sec.getSteps().remove(step)) return;
        }
    }

    public void removeStepsIf(Predicate<RouteStep> pred) {
        if (sections == null) return;
        for (RouteSection sec : sections) {
            if (sec.getSteps() != null) sec.getSteps().removeIf(pred);
        }
    }

    public RouteStep getActiveStep() {
        if (sections == null) return null;
        for (RouteSection sec : sections) {
            if (sec.getSteps() == null) continue;
            for (RouteStep s : sec.getSteps()) if (!s.isCompleted()) return s;
        }
        return null;
    }

    public boolean isComplete() {
        return getAllSteps().stream().allMatch(RouteStep::isCompleted);
    }

    public void resetProgress() {
        getAllSteps().forEach(s -> {
            s.setCompleted(false);
            s.setLocationReached(false);
            s.setSellArmed(false);
            s.setPickupBaseline(null);
            s.setNpcKillProgress(0);
        });
    }
}

package com.routeplanner.model;

public enum StepType {
    LOCATION,
    ITEM,
    SKILLING,
    TELEPORT,
    NOTE
}

package com.routeplanner.model;

import lombok.Data;
import net.runelite.api.coords.WorldPoint;

@Data
public class RouteStep {
    private String name;
    private StepType type;
    private WorldPoint worldPoint;
    private int targetId;
    private boolean completed;
    private transient boolean locationReached; // true once player reached worldPoint; nav visuals off (sticky)
    private String sectionId;   // which RouteSection this step belongs to

    // Agility task fields
    private String agilityCourse;
    private String agilityGoalType;
    private long agilityGoalValue;

    // Quest step fields
    private String questName;          // matches net.runelite.api.Quest enum name
    private boolean questComplete;     // true = auto-complete step when quest is FINISHED

    // Item/Bank step fields
    private String itemList;  // comma separated, / for alternatives e.g. "Spade,Rune pouch/Divine Rune pouch"
    private String itemMode = "BANK";  // "BANK" (fetch from bank), "SHOP" (buy), or "SELL" (sell to shop)
    private transient boolean sellArmed = false;  // SELL: true once items seen in inventory
    private transient java.util.Map<String, Long> pickupBaseline;  // PICKUP: inventory counts when step became active

    // Guided quest (Quest Helper) step fields
    private int questStopIndex = -1;   // flat step index to stop at, -1 = whole quest
    private String questStopText;       // display text of the stop step

    // Teleport step fields
    private String teleportSpell;     // spell name e.g. "Varrock Teleport"
    private net.runelite.api.coords.WorldPoint teleportDestination; // destination WorldPoint
    private int teleportSpellId;      // widget child ID for highlighting  // matches net.runelite.api.Quest enum name

    private String teleportMethod;    // Phase 2: "SPELL" or "ITEM" (null = walk only)
    private String teleportItem;      // Phase 2: item name for ITEM teleports (e.g. "Amulet of glory")

    // Skilling step fields
    private String skillingSkill;      // e.g. "THIEVING"
    private String skillingGoalType;   // "XP_GAIN", "XP_TARGET", "LEVEL"
    private long skillingGoalValue;    // target value
    private long skillingStartXp;      // XP when step became active
    private long skillingProgress;     // current XP gained (for XP_GAIN)
    private String skillingTargetNpc;  // NPC to highlight (e.g. "Knight of Ardougne")
    private String skillingTargetObject; // game object to highlight (e.g. "Baker's stall")
    private String gearReminder; // fishing gear reminder (e.g. "Fly fishing rod, Feathers")
    private String herblorePotion; // potion for Herblore steps (drives the bank highlight)
    private String bankHighlightItems; // generic bank highlight for skilling steps (Cooking, etc.)

    // Transition point: when set, this step has two phases.
    // Phase 1: path to transitionPoint (the staircase/ladder tile).
    // Phase 2: once player plane matches worldPoint plane, path to worldPoint.
    private WorldPoint transitionPoint;
    private int transitionObjectId = -1; // game object ID to highlight as the transition object (-1 = none)

    // Note step (informational, not tracked)
    private String noteText;
    private String npcHighlight; // NOTE step: optional NPC name to highlight
    private boolean highlightEnabled; // master toggle: light up this step's in-game targets (default off)
    private String recipeLabel; // editor: the exact recipe/method dropdown label chosen (for reverse-prefill)
    private int npcKillCount;    // NOTE step: kills to auto-complete (0 = manual)
    private transient int npcKillProgress; // kills so far while this step is active
    private String dialogOptions;          // NOTE step: chat option sequence to highlight, e.g. "3,1""

    public RouteStep(String name, StepType type, WorldPoint worldPoint, int targetId) {
        this.name = name;
        this.type = type;
        this.worldPoint = worldPoint;
        this.targetId = targetId;
        this.completed = false;
    }

    // Constructor for skilling steps
    public RouteStep(String name, String skill, String goalType, long goalValue, long startXp) {
        this.name = name;
        this.type = StepType.SKILLING;
        this.worldPoint = null;
        this.targetId = -1;
        this.completed = false;
        this.skillingSkill = skill;
        this.skillingGoalType = goalType;
        this.skillingGoalValue = goalValue;
        this.skillingStartXp = startXp;
        this.skillingProgress = 0;
    }

    // --- Component presence helpers (Phase 2) ---
    // A component is a view over fields the step already carries.
    // Descriptive only; nothing branches on these yet.

    public boolean hasLocation() {
        return worldPoint != null || teleportMethod != null;
    }

    public boolean hasItems() {
        return (itemList != null && !itemList.trim().isEmpty())
            || "DEPOSIT_ALL".equals(itemMode);
    }

    public boolean hasSkillGoal() {
        return skillingSkill != null && !skillingSkill.trim().isEmpty();
    }

    public boolean hasHighlight() {
        return (skillingTargetNpc != null && !skillingTargetNpc.trim().isEmpty())
            || (skillingTargetObject != null && !skillingTargetObject.trim().isEmpty())
            || (npcHighlight != null && !npcHighlight.trim().isEmpty());
    }

    public boolean hasQuest() {
        return questName != null && !questName.trim().isEmpty();
    }

    public boolean hasNote() {
        return noteText != null && !noteText.trim().isEmpty();
    }
}

package com.routeplanner;

import com.routeplanner.model.Route;
import com.routeplanner.model.RouteStep;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;

public class RouteHudOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final RoutePlannerConfig config;
    private final com.routeplanner.bank.BankItemManager bankItemManager;

    private static final Color BG_COLOR      = new Color(52, 40, 24, 64);   // OSRS brown @ ~25% opacity
    private static final Color TITLE_COLOR   = new Color(255, 152, 31);     // OSRS orange
    private static final Color CURRENT_COLOR = new Color(255, 235, 200);    // warm cream
    private static final Color NEXT_COLOR    = new Color(190, 170, 140);    // muted tan
    private static final Color BORDER_COLOR  = new Color(160, 130, 85, 180); // tan/gold edge
    private static final Color HAVE_COLOR    = new Color(110, 210, 90);     // soft green

    @Inject
    public RouteHudOverlay(Client client, RoutePlannerPlugin plugin, RoutePlannerConfig config,
                           com.routeplanner.bank.BankItemManager bankItemManager) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.bankItemManager = bankItemManager;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.MED);
        setMovable(true);
        setResizable(false);
        setSnappable(true);
    }

    private java.util.List<String> wrapText(String s, int maxChars) {
        java.util.List<String> out = new java.util.ArrayList<>();
        if (s == null) return out;
        StringBuilder cur = new StringBuilder();
        for (String word : s.split(" ")) {
            if (cur.length() > 0 && cur.length() + word.length() + 1 > maxChars) {
                out.add(cur.toString());
                cur = new StringBuilder();
            }
            if (cur.length() > 0) cur.append(" ");
            cur.append(word);
        }
        if (cur.length() > 0) out.add(cur.toString());
        return out;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Route activeRoute = plugin.getActiveRoute();

        if (activeRoute == null) return null;

        int fontStyle = config.hudFontBold() ? Font.BOLD : Font.PLAIN;
        graphics.setFont(config.hudFontFamily().toFont(config.hudFontSize(), fontStyle));
        FontMetrics fm = graphics.getFontMetrics();
        int lineHeight = fm.getHeight() + 3;
        int padding = 7;

        // Build content: [text, color]
        java.util.List<String[]> lines = new java.util.ArrayList<>();

        // Determine if we should show route steps or agility task
        boolean routeHasIncompleteStep = false;
        int routeCurrentIdx = -1;
        List<RouteStep> steps = activeRoute != null ? activeRoute.getSteps() : new java.util.ArrayList<>();

        if (activeRoute != null) {
            for (int i = 0; i < steps.size(); i++) {
                if (!steps.get(i).isCompleted()) {
                    routeCurrentIdx = i;
                    routeHasIncompleteStep = true;
                    break;
                }
            }
        }

        // Route fully complete (or empty): hide the HUD entirely
        if (activeRoute != null && !routeHasIncompleteStep) {
            return null;
        }

        // Show route name as title always
        if (activeRoute != null) {
            lines.add(new String[]{activeRoute.getName(), "TITLE"});
        }

        // Show route location step if there is one incomplete
        if (routeHasIncompleteStep) {
            RouteStep current = steps.get(routeCurrentIdx);
            String curPrefix = ">> " + (routeCurrentIdx + 1) + ". ";
            java.util.List<String> curWrapped = wrapText(curPrefix + current.getName(), 42);
            for (int i = 0; i < curWrapped.size(); i++) {
                String curLine = i == 0 ? curWrapped.get(i) : "     " + curWrapped.get(i);
                lines.add(new String[]{curLine, "CURRENT"});
            }
            if (routeCurrentIdx + 1 < steps.size()) {
                RouteStep next = steps.get(routeCurrentIdx + 1);
                String nxtPrefix = "   " + (routeCurrentIdx + 2) + ". ";
                java.util.List<String> nxtWrapped = wrapText(nxtPrefix + next.getName(), 42);
                for (int i = 0; i < nxtWrapped.size(); i++) {
                    String nxtLine = i == 0 ? nxtWrapped.get(i) : "     " + nxtWrapped.get(i);
                    lines.add(new String[]{nxtLine, "NEXT"});
                }
            }
        }

        // Item checklist section for ITEM steps
        if (routeHasIncompleteStep) {
            RouteStep curStep = steps.get(routeCurrentIdx);
            if (curStep.hasItems()) {
                lines.add(new String[]{"---", "DIM"});
                String mode = curStep.getItemMode();
                if ("SELL".equals(mode)) {
                    lines.add(new String[]{"Sell:", "TITLE"});
                    for (String[] st : bankItemManager.getSellStatusList(curStep.getItemList())) {
                        boolean sold = st[1].equals("SOLD");
                        String mark = sold ? "[x] " : "[  ] ";
                        lines.add(new String[]{"  " + mark + st[0], sold ? "HAVE" : "CURRENT"});
                    }
                } else {
                    String header = "SHOP".equals(mode) ? "Buy:" : ("PICKUP".equals(mode) ? "Pick up:" : "Gather:");
                    lines.add(new String[]{header, "TITLE"});
                    java.util.Map<String, Long> baseline = "PICKUP".equals(curStep.getItemMode())
                        ? curStep.getPickupBaseline() : null;
                    for (String[] st : bankItemManager.getItemStatusList(curStep.getItemList(), baseline)) {
                        boolean have = st[1].equals("HAVE");
                        String mark = have ? "[x] " : "[  ] ";
                        lines.add(new String[]{"  " + mark + st[0], have ? "HAVE" : "CURRENT"});
                    }
                }
            }
        }

        // Note step section (informational, not tracked)
        if (routeHasIncompleteStep) {
            RouteStep curStep = steps.get(routeCurrentIdx);
            if (curStep.hasNote()) {
                lines.add(new String[]{"---", "DIM"});
                String note = (curStep.getNoteText() != null && !curStep.getNoteText().isEmpty())
                    ? curStep.getNoteText() : curStep.getName();
                for (String para : note.split("\\r?\\n")) {
                    if (para.trim().isEmpty()) continue;
                    for (String wrapped : wrapText(para, 42)) {
                        lines.add(new String[]{wrapped, "CURRENT"});
                    }
                }
                if (curStep.getNpcKillCount() > 0) {
                    lines.add(new String[]{"Kills: " + curStep.getNpcKillProgress()
                        + " / " + curStep.getNpcKillCount(), "TITLE"});
                } else {
                    // Only show "mark complete" if no component will auto-complete the step
                    boolean hasAutoComplete = curStep.hasItems() || curStep.hasSkillGoal()
                        || (curStep.hasQuest() && curStep.isQuestComplete())
                        || curStep.getWorldPoint() != null;
                    if (!hasAutoComplete) {
                        lines.add(new String[]{"(mark complete to continue)", "DIM"});
                    }
                }
            }
        }

        // Add XP tracker section if there is an active skilling step
        if (plugin.getActiveRoute() != null) {
            for (com.routeplanner.model.RouteStep s : plugin.getActiveRoute().getSteps()) {
                if (!s.isCompleted() && s.hasSkillGoal()
                        && s.getSkillingGoalType() != null) {
                    String sk = s.getSkillingSkill() != null
                        ? s.getSkillingSkill().substring(0,1).toUpperCase()
                          + s.getSkillingSkill().substring(1).toLowerCase() : "?";
                    net.runelite.api.Skill apiSk = null;
                    try { apiSk = net.runelite.api.Skill.valueOf(
                        s.getSkillingSkill().toUpperCase()); } catch (Exception ignored) {}
                    int curLvl = apiSk != null ? client.getRealSkillLevel(apiSk) : 0;
                    long curXp = apiSk != null ? client.getSkillExperience(apiSk) : 0;

                    lines.add(new String[]{"---", "DIM"});
                    String gt = s.getSkillingGoalType();
                    if (gt.equals("XP_GAIN")) {
                        lines.add(new String[]{sk + " XP Gained:", "TITLE"});
                        lines.add(new String[]{"  +" + String.format("%,d", s.getSkillingProgress())
                            + " / +" + String.format("%,d", s.getSkillingGoalValue()), "CURRENT"});
                    } else if (gt.equals("XP_TARGET")) {
                        lines.add(new String[]{sk + " Total XP:", "TITLE"});
                        lines.add(new String[]{"  " + String.format("%,d", curXp)
                            + " / " + String.format("%,d", s.getSkillingGoalValue()), "CURRENT"});
                    } else if (gt.equals("LEVEL")) {
                        lines.add(new String[]{sk + " Level:", "TITLE"});
                        lines.add(new String[]{"  " + curLvl + " / " + s.getSkillingGoalValue(), "CURRENT"});
                    }
                    lines.add(new String[]{"Lvl: " + curLvl, "NEXT"});
                    break;
                }
            }
        }

        // Calculate size
        int maxWidth = 0;
        for (String[] line : lines) {
            int w = fm.stringWidth(line[0]);
            if (w > maxWidth) maxWidth = w;
        }
        int width = maxWidth + padding * 2 + 4;
        int totalHeight = padding * 2 + lines.size() * lineHeight;

        // Theme palette
        com.routeplanner.HudTheme theme = config.hudTheme();
        Color bgC, borderC, titleC, currentC, nextC, haveC, dimC, dividerC;
        if (theme == com.routeplanner.HudTheme.QUEST_HELPER) {
            bgC      = new Color(70, 61, 50, 156);   // RuneLite standard overlay background
            borderC  = new Color(60, 60, 60, 140);
            titleC   = new Color(255, 255, 255);
            currentC = new Color(255, 255, 255);
            nextC    = new Color(190, 190, 190);
            haveC    = new Color(0, 255, 0);
            dimC     = new Color(170, 170, 170);
            dividerC = new Color(255, 255, 255, 40);
        } else if (theme == com.routeplanner.HudTheme.CUSTOM) {
            bgC      = config.hudBgColor();
            borderC  = config.hudBorderColor();
            titleC   = config.hudTitleColor();
            currentC = config.hudCurrentColor();
            nextC    = config.hudNextColor();
            haveC    = config.hudHaveColor();
            dimC     = config.hudDimColor();
            dividerC = config.hudDividerColor();
        } else { // OSRS_BROWN (default)
            bgC      = BG_COLOR;
            borderC  = BORDER_COLOR;
            titleC   = TITLE_COLOR;
            currentC = CURRENT_COLOR;
            nextC    = NEXT_COLOR;
            haveC    = HAVE_COLOR;
            dimC     = new Color(155, 135, 105);
            dividerC = new Color(185, 145, 85, 45);
        }

        // Background
        graphics.setColor(bgC);
        graphics.fillRoundRect(0, 0, width, totalHeight, 6, 6);
        boolean drawOutline = theme != com.routeplanner.HudTheme.CUSTOM || config.hudOutline();
        if (drawOutline) {
            int thickness = theme == com.routeplanner.HudTheme.CUSTOM ? Math.max(1, config.hudBorderThickness()) : 1;
            graphics.setColor(borderC);
            graphics.setStroke(new BasicStroke(thickness));
            graphics.drawRoundRect(0, 0, width - 1, totalHeight - 1, 6, 6);
        }

        // Text
        int y = padding + fm.getAscent();
        for (String[] line : lines) {
            Color color;
            switch (line[1]) {
                case "TITLE":   color = titleC; break;
                case "CURRENT": color = currentC; break;
                case "NEXT":    color = nextC; break;
                case "HAVE":    color = haveC; break;
                default:        color = dimC; break;
            }
            if (line[0].equals("---")) {
                graphics.setColor(dividerC);
                graphics.drawLine(padding, y - fm.getAscent() / 2, width - padding, y - fm.getAscent() / 2);
                y += lineHeight / 2;
                continue;
            }
            // dark shadow for legibility over the transparent background
            graphics.setColor(new Color(0, 0, 0, 190));
            graphics.drawString(line[0], padding + 1, y + 1);
            graphics.setColor(color);
            graphics.drawString(line[0], padding, y);
            y += lineHeight;
        }

        return new Dimension(width, totalHeight);
    }
}

