import javax.inject.Inject;
import java.awt.*;

public class MinimapOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final RoutePlannerConfig config;
    private final WorldMapOverlay worldMapOverlay;

    @Inject
    public MinimapOverlay(Client client, RoutePlannerPlugin plugin, RoutePlannerConfig config, WorldMapOverlay worldMapOverlay) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.worldMapOverlay = worldMapOverlay;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;

        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || step.getWorldPoint() == null) return null;

        drawMinimapDot(graphics, step.getWorldPoint());
        return null;
    }

    private void drawMinimapDot(Graphics2D graphics, WorldPoint worldPoint) {
        Point minimapPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(worldPoint);
        if (minimapPoint == null) return;

        int x = minimapPoint.getX();
        int y = minimapPoint.getY();
        int size = 6;

        graphics.setColor(Color.BLACK);
        graphics.fillOval(x - size / 2 - 1, y - size / 2 - 1, size + 2, size + 2);

        graphics.setColor(config.minimapColor());
        graphics.fillOval(x - size / 2, y - size / 2, size, size);
    }
}

package com.routeplanner;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Loads transport edges (origin -> destination) from the bundled Shortest Path
 * TSV datasets. Only rows with BOTH a valid origin and destination are kept,
 * which naturally includes doors, stairs, dungeon entrances, agility shortcuts,
 * boats, ships and minecarts, and skips "from anywhere" teleports / hub types.
 */
@Slf4j
public class TransportLoader {

    // Files that contain simple origin->destination edges
    private static final String[] FILES = {
        "transports.tsv",
        "agility_shortcuts.tsv",
        "boats.tsv",
        "ships.tsv",
        "charter_ships.tsv",
        "minecarts.tsv"
    };

    public static Map<WorldPoint, List<WorldPoint>> load() {
        Map<WorldPoint, List<WorldPoint>> edges = new HashMap<>();
        int total = 0;
        for (String f : FILES) {
            int count = 0;
            try (InputStream is = TransportLoader.class.getResourceAsStream(
                    "/com/routeplanner/transports/" + f)) {
                if (is == null) { log.warn("Transport file missing: {}", f); continue; }
                BufferedReader br = new BufferedReader(new InputStreamReader(is));
                String line;
                while ((line = br.readLine()) != null) {
                    if (line.isEmpty() || line.startsWith("#")) continue;
                    String[] cols = line.split("\t");
                    if (cols.length < 2) continue;
                    WorldPoint origin = parsePoint(cols[0]);
                    WorldPoint dest = parsePoint(cols[1]);
                    if (origin == null || dest == null) continue;
                    edges.computeIfAbsent(origin, k -> new ArrayList<>()).add(dest);
                    count++;
                }
            } catch (Exception e) {
                log.warn("Failed to load transport file {}: {}", f, e.toString());
            }
            log.info("TransportLoader: {} edges from {}", count, f);
            total += count;
        }
        log.info("TransportLoader: {} total edges across {} origins", total, edges.size());
        return edges;
    }

    private static WorldPoint parsePoint(String s) {
        if (s == null) return null;
        s = s.trim();
        if (s.isEmpty()) return null;
        String[] parts = s.split("\\s+");
        if (parts.length < 3) return null;
        try {
            return new WorldPoint(Integer.parseInt(parts[0]),
                Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

package com.routeplanner;

import com.routeplanner.model.Route;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.Arrays;
import java.util.List;

@Slf4j
public class RouteImportExport {

    private final RoutePlannerPlugin plugin;
    private final RoutePlannerPanel panel;

    public RouteImportExport(RoutePlannerPlugin plugin, RoutePlannerPanel panel) {
        this.plugin = plugin;
        this.panel = panel;
    }

    public void exportRoute(Route route) {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Export Route");
        chooser.setSelectedFile(new File(route.getName().replaceAll("[^a-zA-Z0-9_-]", "_") + ".json"));
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showSaveDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        if (!file.getName().endsWith(".json")) {
            file = new File(file.getAbsolutePath() + ".json");
        }

        try {
            String json = plugin.getRouteGson().toJson(route);
            Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
            JOptionPane.showMessageDialog(null,
                "Route exported to:\n" + file.getAbsolutePath(),
                "Export Successful", JOptionPane.INFORMATION_MESSAGE);
            log.info("Exported route {} to {}", route.getName(), file.getAbsolutePath());
        } catch (IOException e) {
            log.error("Failed to export route", e);
            JOptionPane.showMessageDialog(null,
                "Export failed: " + e.getMessage(),
                "Export Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    public void exportAllRoutes() {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Export All Routes");
        chooser.setSelectedFile(new File("routes_export.json"));
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showSaveDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        if (!file.getName().endsWith(".json")) {
            file = new File(file.getAbsolutePath() + ".json");
        }

        try {
            String json = plugin.getRouteGson().toJson(plugin.getRoutes());
            Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
            JOptionPane.showMessageDialog(null,
                "All routes exported to:\n" + file.getAbsolutePath(),
                "Export Successful", JOptionPane.INFORMATION_MESSAGE);
        } catch (IOException e) {
            log.error("Failed to export routes", e);
            JOptionPane.showMessageDialog(null,
                "Export failed: " + e.getMessage(),
                "Export Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    /**
     * A JFileChooser using the platform's native look and feel (GTK on Linux, etc.) instead of
     * Swing's default cross-platform "Metal" theme, which several users found looked out of place
     * and confusing to navigate. Falls back silently to the default chooser if the system L&F
     * can't be set for any reason -- this is cosmetic, never worth failing an import/export over.
     */
    private JFileChooser newSystemFileChooser(String title) {
        // Use cross-platform look and feel for the file chooser so it works
        // correctly on Linux regardless of whether running under Wine or native.
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle(title);
        return chooser;
    }

    public void importRoute() {
        JFileChooser chooser = newSystemFileChooser("Import Route");
        chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

        int result = chooser.showOpenDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        try {
            String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);

            // Try single route first
            try {
                Route route = plugin.getRouteGson().fromJson(json, Route.class);
                if (route != null) route.migrateIfNeeded();
                if (route != null && route.getName() != null) {
                    String name = route.getName();
                    boolean exists = plugin.getRoutes().stream()
                        .anyMatch(r -> r.getName().equalsIgnoreCase(name));
                    if (exists) {
                        route.setName(name + " (imported)");
                    }
                    plugin.getRoutes().add(route);
                    plugin.saveRoutesPublic();
                    plugin.setActiveRoute(route);
                    JOptionPane.showMessageDialog(null,
                        "Route \"" + route.getName() + "\" imported!",
                        "Import Successful", JOptionPane.INFORMATION_MESSAGE);
                    log.info("Imported route: {}", route.getName());
                    return;
                }
            } catch (Exception ignored) {}

            // Try list of routes
            Route[] routes = plugin.getRouteGson().fromJson(json, Route[].class);
            if (routes != null) for (Route r : routes) r.migrateIfNeeded();
            if (routes != null && routes.length > 0) {
                int imported = 0;
                for (Route route : routes) {
                    if (route.getName() == null) continue;
                    String name = route.getName();
                    boolean exists = plugin.getRoutes().stream()
                        .anyMatch(r -> r.getName().equalsIgnoreCase(name));
                    if (exists) route.setName(name + " (imported)");
                    plugin.getRoutes().add(route);
                    imported++;
                }
                plugin.saveRoutesPublic();
                panel.refresh();
                JOptionPane.showMessageDialog(null,
                    imported + " route(s) imported!",
                    "Import Successful", JOptionPane.INFORMATION_MESSAGE);
            }

        } catch (Exception e) {
            log.error("Failed to import route", e);
            JOptionPane.showMessageDialog(null,
                "Import failed: " + e.getMessage(),
                "Import Error", JOptionPane.ERROR_MESSAGE);
        }
    }
}

