    private void applyMode() {
        boolean dev = plugin.getConfig() == null
            || plugin.getConfig().mode() == com.routeplanner.RouteMode.DEVELOPER;
        if (addRouteBtn != null) addRouteBtn.setVisible(dev);
        if (exportBtn != null) exportBtn.setVisible(dev);
        if (addStepHeaderBtn != null) addStepHeaderBtn.setVisible(dev);
        if (addSectionBtn != null) addSectionBtn.setVisible(dev);
        updateHistoryButtons(dev);
        syncEditModeToggle(dev);
    }

    public void refresh() {
        SwingUtilities.invokeLater(() -> {
            applyMode();
            routeListPanel.removeAll();
            stepListPanel.removeAll();

            // Populate route list
            for (Route route : plugin.getRoutes()) {
                JPanel row = new JPanel(new BorderLayout());
                row.setBackground(route == plugin.getActiveRoute()
                    ? ColorScheme.BRAND_ORANGE_TRANSPARENT
                    : ColorScheme.DARKER_GRAY_COLOR);
                row.setBorder(new EmptyBorder(4, 6, 4, 6));
                // Was a fixed 32px (one line only); a plain JLabel doesn't wrap on its own, so a
                // long route name either overflowed the row width (forcing a horizontal scroll on
                // the whole list) or got silently clipped. Wrapping the label in HTML lets it break
                // onto a second line, and the row's cap is raised to 48px so that second line has
                // somewhere to actually render instead of being cut off.
                row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));

                JLabel name = new JLabel("<html><div style='width:150px;'>"
                    + escapeRouteName(route.getName()) + "</div></html>");
                name.setForeground(Color.WHITE);
                row.add(name, BorderLayout.CENTER);

                // Right-click context menu for route
                JPopupMenu routeMenu = new JPopupMenu();
                JMenuItem deleteRoute = new JMenuItem("Delete Route");
                deleteRoute.addActionListener(e -> {
                    int c = JOptionPane.showConfirmDialog(RoutePlannerPanel.this,
                        "Delete route \"" + route.getName() + "\" and its "
                            + route.getAllSteps().size() + " step(s)?\nThis cannot be undone.",
                        "Delete Route", JOptionPane.YES_NO_OPTION);
                    if (c == JOptionPane.YES_OPTION) plugin.deleteRoute(route);
                });
                JMenuItem renameRoute = new JMenuItem("Rename Route");
                renameRoute.addActionListener(e -> {
                    String newName = JOptionPane.showInputDialog(this,
                        "Route name:", route.getName());
                    if (newName != null && !newName.trim().isEmpty()
                            && !newName.trim().equals(route.getName())) {
                        route.setName(newName.trim());
                        plugin.saveRoutesPublic();
                        refresh();
                    }
                });
                JMenuItem resetRoute = new JMenuItem("Reset Progress");
                resetRoute.addActionListener(e -> { plugin.resetRoute(route); });
                JMenuItem toggleRepeat = new JMenuItem(
                    route.isRepeatable() ? "Repeatable: ON" : "Repeatable: OFF");
                toggleRepeat.addActionListener(e -> {
                    route.setRepeatable(!route.isRepeatable());
                    plugin.saveRoutesPublic();
                    refresh();
                });
                routeMenu.add(renameRoute);
                routeMenu.add(toggleRepeat);
                routeMenu.add(resetRoute);
                routeMenu.add(deleteRoute);
                row.addMouseListener(new MouseAdapter() {
                    @Override
                    public void mousePressed(MouseEvent e) {
                        if (SwingUtilities.isLeftMouseButton(e)) {
                            // Click active route again to deselect (pause)
                            if (plugin.getActiveRoute() == route) {
                                plugin.setActiveRoute(null);
                            } else {
                                plugin.setActiveRoute(route);
                            }
                        }
                        if (e.isPopupTrigger()) {
                            routeMenu.show(row, e.getX(), e.getY());
                        }
                    }
                    @Override
                    public void mouseReleased(MouseEvent e) {
                        if (e.isPopupTrigger()) {
                            routeMenu.show(row, e.getX(), e.getY());
                        }
                    }
                });

                routeListPanel.add(row);
                routeListPanel.add(Box.createVerticalStrut(2));
            }

            // Steps section directly below routes
            Route active = plugin.getActiveRoute();
            if (active != null) {
                activeRouteLabel.setText("Active: " + active.getName()
                    + " (" + active.getSteps().stream().filter(RouteStep::isCompleted).count()
                    + "/" + active.getSteps().size() + ")");

                // Drop a stale section selection from a previous route
                if (selectedSectionId != null && active.findSection(selectedSectionId) == null) {
                    selectedSectionId = null;
                }

                rowStepMap.clear();
                rowSectionMap.clear();
                for (com.routeplanner.model.RouteSection section : active.getSections()) {
                    boolean dev = plugin.getConfig() == null
                        || plugin.getConfig().mode() == com.routeplanner.RouteMode.DEVELOPER;

                    JPanel secRow = new JPanel(new BorderLayout());
                    boolean isSelected = section.getId().equals(selectedSectionId);
                    secRow.setBackground(isSelected ? new Color(70, 55, 25) : new Color(45, 45, 45));
                    secRow.setBorder(new EmptyBorder(5, 6, 5, 6));
                    secRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

                    int total = section.getSteps().size();
                    long done = section.getSteps().stream().filter(RouteStep::isCompleted).count();
                    String arrow = section.isCollapsed() ? "+ " : "- ";
                    JLabel secLabel = new JLabel(arrow + section.getName() + "  (" + done + "/" + total + ")");
                    secLabel.setForeground(isSelected ? new Color(255, 180, 80) : Color.WHITE);
                    secLabel.setFont(secLabel.getFont().deriveFont(Font.BOLD, 13f));
                    secRow.add(secLabel, BorderLayout.CENTER);

                    JPopupMenu secMenu = new JPopupMenu();
                    JMenuItem renameSec = new JMenuItem("Rename Section");
                    renameSec.addActionListener(ev -> {
                        String nn = JOptionPane.showInputDialog(this, "Section name:", section.getName());
                        if (nn != null && !nn.trim().isEmpty()) {
                            String rnErr = RouteTextValidator.checkField("Section name", nn.trim());
                            if (rnErr != null) { JOptionPane.showMessageDialog(this, rnErr, "Links not allowed", JOptionPane.WARNING_MESSAGE); return; }
                            section.setName(nn.trim());
                            plugin.saveRoutesPublic();
                            refresh();
                        }
                    });
                    java.util.List<com.routeplanner.model.RouteSection> secList = active.getSections();
                    JMenuItem moveSecUp = new JMenuItem("Move Up");
                    moveSecUp.addActionListener(ev -> {
                        int i = secList.indexOf(section);
                        if (i > 0) {
                            java.util.Collections.swap(secList, i, i - 1);
                            plugin.saveRoutesPublic();
                            refresh();
                        }
                    });
                    JMenuItem moveSecDown = new JMenuItem("Move Down");
                    moveSecDown.addActionListener(ev -> {
                        int i = secList.indexOf(section);
                        if (i >= 0 && i < secList.size() - 1) {
                            java.util.Collections.swap(secList, i, i + 1);
                            plugin.saveRoutesPublic();
                            refresh();
                        }
                    });
                    long secDone = section.getSteps().stream().filter(RouteStep::isCompleted).count();
                    boolean allDone = !section.getSteps().isEmpty() && secDone == section.getSteps().size();
                    JMenuItem markSec = new JMenuItem(allDone ? "Mark Section Incomplete" : "Mark Section Complete");
                    markSec.addActionListener(ev -> {
                        for (RouteStep s : section.getSteps()) {
                            s.setCompleted(!allDone);
                            if (allDone) plugin.resetStepProgress(s); // un-completing -> reset
                        }
                        plugin.saveRoutesPublic();
                        refresh();
                    });
                    JMenuItem deleteSec = new JMenuItem("Delete Section");
                    deleteSec.addActionListener(ev -> {
                        int c = JOptionPane.showConfirmDialog(this,
                            "Delete section \"" + section.getName() + "\" and its "
                                + section.getSteps().size() + " step(s)?",
                            "Delete Section", JOptionPane.YES_NO_OPTION);
                        if (c == JOptionPane.YES_OPTION) {
                            active.getSections().remove(section);
                            if (section.getId().equals(selectedSectionId)) selectedSectionId = null;
                            plugin.saveRoutesPublic();
                            refresh();
                        }
                    });
                    if (dev) { secMenu.add(moveSecUp); secMenu.add(moveSecDown); secMenu.add(markSec); secMenu.add(renameSec); secMenu.add(deleteSec); }
                    else { secMenu.add(markSec); }

                    final JPanel finalSecRow = secRow;
                    final com.routeplanner.model.RouteSection finalSection = section;
                    MouseAdapter secMa = new MouseAdapter() {
                        @Override public void mousePressed(MouseEvent e) {
                            if (e.isPopupTrigger()) { final int mx = e.getX(), my = e.getY(); SwingUtilities.invokeLater(() -> secMenu.show(finalSecRow, mx, my)); return; }
                            if (SwingUtilities.isLeftMouseButton(e)) {
                                selectedSectionId = finalSection.getId();
                                finalSection.setCollapsed(!finalSection.isCollapsed());
                                plugin.saveRoutesPublic();
                                refresh();
                            }
                        }
                        @Override public void mouseReleased(MouseEvent e) {
                            if (e.isPopupTrigger()) { final int mx = e.getX(), my = e.getY(); SwingUtilities.invokeLater(() -> secMenu.show(finalSecRow, mx, my)); }
                        }
                    };
                    secRow.addMouseListener(secMa);
                    secLabel.addMouseListener(secMa);

                    rowSectionMap.put(secRow, section);
                    stepListPanel.add(secRow);
                    stepListPanel.add(Box.createVerticalStrut(2));

                    if (section.isCollapsed()) continue;

                    int num = 0;
                    for (RouteStep step : section.getSteps()) {
                        num++;
                        JPanel row = new JPanel(new BorderLayout());
                        row.setBackground(step.isCompleted() ? new Color(30, 60, 30) : ColorScheme.DARKER_GRAY_COLOR);
                        row.setBorder(new EmptyBorder(5, 14, 5, 8));

                        String mark = step.isCompleted() ? "\u2713" : "\u25CB";
                        String markColor = step.isCompleted() ? "#7fdf7f" : "#9a9a9a";
                        String typeTag = dev
                            ? " <font color='#8a8a8a'>[" + step.getType().name() + "]</font>" : "";
                        String html = "<html><body style='width:168px'>"
                            + "<font color='" + markColor + "'>" + mark + "</font> "
                            + num + ". " + htmlEscape(step.getName())
                            + typeTag
                            + "</body></html>";
                        JLabel stepLabel = new JLabel(html);
                        stepLabel.setForeground(step.isCompleted() ? new Color(150, 230, 150) : Color.WHITE);
                        row.add(stepLabel, BorderLayout.CENTER);
                        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));


                        JPopupMenu stepMenu = new JPopupMenu();
                        JMenuItem deleteStep = new JMenuItem("Delete Step");
                        deleteStep.addActionListener(ev -> plugin.removeStep(active, step));
                        JMenuItem editStep = new JMenuItem("Edit Step");
                        editStep.addActionListener(ev -> new StepEditorDialog(plugin, plugin.getActiveRoute(), step).setVisible(true));
                        JMenuItem completeStep = new JMenuItem(step.isCompleted() ? "Mark Incomplete" : "Mark Complete");
                        completeStep.addActionListener(ev -> {
                            if (step.isCompleted()) {
                                step.setCompleted(false);
                                plugin.resetStepProgress(step);
                                step.setNpcKillProgress(0);
                                plugin.saveRoutesPublic();
                                refresh();
                            } else {
                                plugin.completeStep(step);
                            }
                        });
                        stepMenu.add(completeStep);
                        JMenu moveToSection = new JMenu("Move to Section");
                        {
                            java.util.List<com.routeplanner.model.RouteSection> allSecs = active.getSections();
                            int others = 0;
                            for (com.routeplanner.model.RouteSection ts : allSecs) {
                                if (ts == section) continue;
                                others++;
                                final com.routeplanner.model.RouteSection targetSec = ts;
                                JMenuItem mv = new JMenuItem(ts.getName());
                                mv.addActionListener(ev -> {
                                    active.removeStep(step);
                                    active.addStepToSection(step, targetSec.getId());
                                    plugin.saveRoutesPublic();
                                    refresh();
                                });
                                moveToSection.add(mv);
                            }
                            if (others == 0) {
                                JMenuItem none = new JMenuItem("(no other sections)");
                                none.setEnabled(false);
                                moveToSection.add(none);
                            }
                        }

                        if (dev) { stepMenu.add(moveToSection); stepMenu.add(editStep); stepMenu.add(deleteStep); }

                        final JPanel finalRow = row;
                        MouseAdapter ma = new MouseAdapter() {
                            @Override public void mousePressed(MouseEvent e) {
                                if (e.isPopupTrigger()) { final int mx = e.getX(), my = e.getY(); SwingUtilities.invokeLater(() -> stepMenu.show(finalRow, mx, my)); return; }
                                if (dev && SwingUtilities.isLeftMouseButton(e)) {
                                    draggedStep = step;
                                    draggedSection = finalSection;
                                    finalRow.setBackground(new Color(95, 95, 95));
                                    return;
                                }
                                if (!dev && SwingUtilities.isLeftMouseButton(e)) {
                                    if (step.isCompleted()) {
                                        step.setCompleted(false);
                                        plugin.resetStepProgress(step);
                                        step.setNpcKillProgress(0);
                                        plugin.saveRoutesPublic();
                                        refresh();
                                    } else {
                                        plugin.completeStep(step);
                                    }
                                }
                            }
                            @Override public void mouseDragged(MouseEvent e) {
                                if (!dev || draggedStep == null) return;
                                java.awt.Point pInList = SwingUtilities.convertPoint(
                                    (java.awt.Component) e.getSource(), e.getPoint(), stepListPanel);
                                java.awt.Component target = nearestDropRow(pInList.y);
                                int newLineY = -1;
                                if (target != null && rowStepMap.get(target) != draggedStep) {
                                    java.awt.Rectangle b = target.getBounds();
                                    // line above or below the target row depending on cursor position
                                    newLineY = (pInList.y < b.y + b.height / 2) ? b.y : b.y + b.height;
                                }
                                if (newLineY != dropLineY) {
                                    dropLineY = newLineY;
                                    stepListPanel.repaint();
                                }
                            }
                            @Override public void mouseReleased(MouseEvent e) {
                                if (e.isPopupTrigger()) { final int mx = e.getX(), my = e.getY(); SwingUtilities.invokeLater(() -> stepMenu.show(finalRow, mx, my)); return; }
                                if (dev && draggedStep != null) {
                                    java.awt.Point pInList = SwingUtilities.convertPoint(
                                        (java.awt.Component) e.getSource(), e.getPoint(), stepListPanel);
                                    dropLineY = -1;
                                    stepListPanel.repaint();
                                    handleStepDrop(pInList);
                                    draggedStep = null;
                                    draggedSection = null;
                                    refresh();
                                }
                            }
                        };
                        row.addMouseListener(ma);
                        row.addMouseMotionListener(ma);
                        stepLabel.addMouseListener(ma);
                        stepLabel.addMouseMotionListener(ma);
                        rowStepMap.put(row, step);
                        rowSectionMap.put(row, finalSection);

                        stepListPanel.add(row);
                        stepListPanel.add(Box.createVerticalStrut(2));
                    }
                }
            } else {
                activeRouteLabel.setText("No active route - click one above");
            }


            routeListPanel.revalidate();
            routeListPanel.repaint();
            stepListPanel.revalidate();
            stepListPanel.repaint();
        });
    }


    private void onNewRoute() {
        String name = JOptionPane.showInputDialog(this, "Route name:", "New Route", JOptionPane.PLAIN_MESSAGE);
        if (name != null && !name.trim().isEmpty()) {
            String err = RouteTextValidator.checkField("Route name", name.trim());
            if (err != null) { JOptionPane.showMessageDialog(this, err, "Links not allowed", JOptionPane.WARNING_MESSAGE); return; }
            plugin.createRoute(name.trim());
        }
    }


    private void onAddSection() {

        if (plugin.getActiveRoute() == null) {
            JOptionPane.showMessageDialog(this, "Select or create a route first.");
            return;
        }
        String name = JOptionPane.showInputDialog(this, "Section name:", "New Section", JOptionPane.PLAIN_MESSAGE);
        if (name == null || name.trim().isEmpty()) return;
        String secErr = RouteTextValidator.checkField("Section name", name.trim());
        if (secErr != null) { JOptionPane.showMessageDialog(this, secErr, "Links not allowed", JOptionPane.WARNING_MESSAGE); return; }
        com.routeplanner.model.RouteSection sec = new com.routeplanner.model.RouteSection(
            java.util.UUID.randomUUID().toString(), name.trim());
        plugin.getActiveRoute().getSections().add(sec);
        selectedSectionId = sec.getId();
        plugin.saveRoutesPublic();
        refresh();
    }
















}

package com.routeplanner.util;

import java.util.regex.Pattern;

/**
 * Validates user-entered route text. Its main job is to keep links out of any free-text field --
 * route names, section names, step names, and note text -- so shared routes cannot be used to point
 * players at external sites. Enforced at creation time (the step editor) and again at import time
 * (the Route Hub), because imported JSON cannot be assumed to have passed through the editor.
 *
 * <p>The link check is deliberately moderate: it catches obvious URLs and common chat-invite shapes,
 * not exotic obfuscation. Determined obfuscation is caught by human review of Route Hub submissions
 * and by the standing "community content" warning, not by regex.
 */
public final class RouteTextValidator {

    private RouteTextValidator() {}

    // http:// or https:// followed by something
    private static final Pattern SCHEME = Pattern.compile("(?i)\\bhttps?://\\S+");
    // www.something
    private static final Pattern WWW = Pattern.compile("(?i)\\bwww\\.\\S+");
    // a bare domain like example.com / foo.gg / bar.io, with a known-ish TLD, optionally with a path.
    // Kept to a curated TLD list so ordinary text ("meet at lvl.99", "1.5m gp") does not trip it.
    private static final Pattern BARE_DOMAIN = Pattern.compile(
        "(?i)\\b[a-z0-9][a-z0-9-]{0,62}\\.(?:com|net|org|io|gg|gved|co|me|tv|xyz|link|site|shop|store|"
        + "info|app|dev|discord|invite)\\b(?:/\\S*)?");
    // explicit well-known invite/link shapes
    private static final Pattern KNOWN = Pattern.compile(
        "(?i)\\b(?:discord\\.gg|discord\\.com/invite|discordapp\\.com/invite|t\\.me|bit\\.ly|"
        + "tinyurl\\.com|youtu\\.be)\\b");

    /** @return true if the text appears to contain a web link or invite. */
    public static boolean containsLink(String text) {
        if (text == null || text.isEmpty()) return false;
        return SCHEME.matcher(text).find()
            || WWW.matcher(text).find()
            || KNOWN.matcher(text).find()
            || BARE_DOMAIN.matcher(text).find();
    }

    /**
     * Check a single field. Returns null if OK, or a short user-facing error message if not.
     * @param label human name of the field, used in the message (e.g. "Step name", "Note")
     */
    public static String checkField(String label, String text) {
        if (containsLink(text)) {
            return label + " can't contain a web link. Please remove it.";
        }
        return null;
    }
}

package com.routeplanner.util;

import com.google.gson.*;
import com.routeplanner.model.Route;
import net.runelite.api.coords.WorldPoint;

import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

public class RouteSerializer {

    private RouteSerializer() {
    }

    public static String toJson(List<Route> routes, Gson gson) {
        return gson.toJson(routes);
    }

    public static List<Route> fromJson(String json, Gson gson) {
        if (json == null || json.isEmpty()) return new ArrayList<>();
        try {
            Type listType = new com.google.gson.reflect.TypeToken<List<Route>>(){}.getType();
            List<Route> loaded = gson.fromJson(json, listType);
            if (loaded != null) { for (Route r : loaded) r.migrateIfNeeded(); }
            return loaded;
        } catch (Exception e) {
            return new ArrayList<>();
        }
    }

    public static class WorldPointAdapter implements JsonSerializer<WorldPoint>, JsonDeserializer<WorldPoint> {
        @Override
        public JsonElement serialize(WorldPoint src, Type typeOfSrc, JsonSerializationContext ctx) {
            JsonObject obj = new JsonObject();
            obj.addProperty("x", src.getX());
            obj.addProperty("y", src.getY());
            obj.addProperty("plane", src.getPlane());
            return obj;
        }

        @Override
        public WorldPoint deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext ctx) {
            JsonObject obj = json.getAsJsonObject();
            return new WorldPoint(
                obj.get("x").getAsInt(),
                obj.get("y").getAsInt(),
                obj.get("plane").getAsInt()
            );
        }
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;

@Slf4j
@Singleton
public class ShopOverlay extends Overlay {

    // Shop stock container: group 300, child 16
    private static final int SHOP_GROUP = 300;
    private static final int SHOP_STOCK_CHILD = 16;

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public ShopOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        String mode = step.getItemMode();
        boolean isSell = "SELL".equals(mode);
        boolean isShop = "SHOP".equals(mode);
        if (!isShop && !isSell) return null;

        // SHOP highlights the shop stock (300,16); SELL highlights the inventory panel (301,0)
        Widget container = isSell
            ? client.getWidget(301, 0)
            : client.getWidget(SHOP_GROUP, SHOP_STOCK_CHILD);
        if (container == null || container.isHidden()) return null;

        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return null;

        Widget[] items = container.getDynamicChildren();
        if (items == null) return null;

        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            boolean isRequired = false;
            boolean isMissing = false;

            for (List<String> group : groups) {
                for (String alt : group) {
                    String altName = bankItemManager.parseItemName(alt);
                    if (itemName.equalsIgnoreCase(altName)) {
                        isRequired = true;
                        if (isSell) {
                            // Item present in inventory = still needs selling -> orange
                            isMissing = true;
                        } else {
                            long required = bankItemManager.parseQuantityValue(alt);
                            long inInventory = countInInventory(altName);
                            isMissing = inInventory < required;
                        }
                        break;
                    }
                }
                if (isRequired) break;
            }

            if (isRequired) {
                Rectangle bounds = new Rectangle(
                    item.getCanvasLocation().getX(),
                    item.getCanvasLocation().getY(),
                    item.getWidth(),
                    item.getHeight()
                );
                Color highlight = isMissing
                    ? new Color(255, 140, 0, 120)
                    : new Color(0, 255, 0, 80);
                Color border = isMissing
                    ? new Color(255, 140, 0, 220)
                    : new Color(0, 255, 0, 200);

                graphics.setColor(highlight);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setColor(border);
                graphics.setStroke(new BasicStroke(2));
                graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }

        return null;
    }

    private long countInInventory(String itemName) {
        ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
        if (inv == null) return 0;
        long total = 0;
        for (Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String name = itemManager.getItemComposition(invItem.getId()).getName();
            if (name != null && name.equalsIgnoreCase(itemName)) {
                total += invItem.getQuantity();
            }
        }
        return total;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.bank.BankSearch;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;

@Slf4j
@Singleton
public class BankFilterButton {

    private static final String FILTER_TEXT = "Route Filter";
    // Bank interface group ID
    private static final int BANK_GROUP_ID = 12;

    @Inject private Client client;
    @Inject private RoutePlannerPlugin plugin;
    @Inject private BankItemManager bankItemManager;
    @Inject private BankSearch bankSearch;
    @Inject private net.runelite.client.game.ItemManager itemManager;

    private boolean filterActive = false;
    private Widget filterButton = null;
    private final java.util.Map<Integer, int[]> originalPositions = new java.util.HashMap<>();

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.BANKMAIN_BUILD) {
            addFilterButton();
            if (filterActive) applyItemFilter();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            filterButton = null;
            filterActive = false;
            originalPositions.clear();
            addFilterButton();
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == BANK_GROUP_ID) {
            filterButton = null;
            filterActive = false;
        }
    }

    private void addFilterButton() {
        if (plugin.getActiveRoute() == null) return;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return;

        Widget bankContainer = client.getWidget(ComponentID.BANK_CONTAINER);
        if (bankContainer == null) return;

        if (filterButton != null && !filterButton.isHidden()) return;

        filterButton = bankContainer.createChild(-1, WidgetType.TEXT);
        filterButton.setText(filterActive
            ? "<col=ff9900>[" + FILTER_TEXT + " ON]</col>"
            : "<col=aaaaaa>[" + FILTER_TEXT + "]</col>");
        filterButton.setOriginalX(340);
        filterButton.setOriginalY(8);
        filterButton.setOriginalWidth(100);
        filterButton.setOriginalHeight(15);
        filterButton.setFontId(495);
        filterButton.setHasListener(true);
        filterButton.setAction(0, "Toggle");
        filterButton.setName(FILTER_TEXT);
        filterButton.setOnOpListener((JavaScriptCallback) e -> toggleFilter());
        filterButton.revalidate();
    }

    private void toggleFilter() {
        filterActive = !filterActive;
        if (filterButton != null) {
            filterButton.setText(filterActive
                ? "<col=ff9900>[" + FILTER_TEXT + " ON]</col>"
                : "<col=aaaaaa>[" + FILTER_TEXT + "]</col>");
        }

        if (filterActive) {
            applyItemFilter();
        } else {
            bankSearch.reset(true);
        }
    }

    private void applyItemFilter() {
        RouteStep step = plugin.getActiveRoute() != null
            ? plugin.getActiveRoute().getActiveStep() : null;
        if (step == null || step.getItemList() == null) return;

        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return;

        // Build set of all required item names (lowercased)
        java.util.Set<String> requiredNames = new java.util.HashSet<>();
        for (List<String> group : groups) {
            for (String alt : group) {
                requiredNames.add(bankItemManager.parseItemName(alt).toLowerCase().trim());
            }
        }


        Widget itemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
        if (itemContainer == null) return;
        Widget[] items = itemContainer.getDynamicChildren();
        if (items == null) return;

        // Save positions first time
        if (originalPositions.isEmpty()) {
            for (Widget item : items) {
                if (item == null) continue;
                originalPositions.put(item.getIndex(),
                    new int[]{item.getOriginalX(), item.getOriginalY()});
            }
        }

        // Sort: required first, hide rest
        java.util.List<Widget> required = new java.util.ArrayList<>();
        for (Widget item : items) {
            if (item == null || item.getItemId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getItemId()).getName();
            if (name == null) { item.setHidden(true); continue; }
            if (requiredNames.contains(name.toLowerCase().trim())) {
                required.add(item);
            } else {
                item.setHidden(true);
            }
        }

        int cols = 8, itemW = 42, itemH = 36, startX = 51, startY = 0;
        for (int i = 0; i < required.size(); i++) {
            Widget item = required.get(i);
            item.setHidden(false);
            item.setOriginalX(startX + (i % cols) * itemW);
            item.setOriginalY(startY + (i / cols) * itemH);
            item.revalidate();
        }
    }

    public void reset() {
        if (filterActive) {
            bankSearch.reset(true);
        }
        filterActive = false;
        filterButton = null;
        originalPositions.clear();
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;

@Slf4j
@Singleton
public class BankOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public BankOverlay(Client client, RoutePlannerPlugin plugin,
                       BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null) return null;

        boolean isItem = step.hasItems();
        boolean isHerblore = step.isHighlightEnabled() && step.getHerblorePotion() != null;
        boolean isBankSkill = step.isHighlightEnabled() && step.getBankHighlightItems() != null
            && !step.getBankHighlightItems().trim().isEmpty();
        if (!isItem && !isHerblore && !isBankSkill) return null;

        // Check if bank is open
        Widget bankContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
        if (bankContainer == null || bankContainer.isHidden()) return null;
        Widget[] items = bankContainer.getDynamicChildren();
        if (items == null) return null;

        String itemListStr;
        if (isItem) {
            itemListStr = step.getItemList();
        } else if (isHerblore) {
            com.routeplanner.skilling.PotionRecipes.Potion pot =
                com.routeplanner.skilling.PotionRecipes.getByName(step.getHerblorePotion());
            if (pot == null) return null;
            if (inventoryHasItem(pot.unfinished)) {
                itemListStr = pot.secondary;
            } else if (bankHasItem(items, pot.unfinished)) {
                itemListStr = pot.unfinished + ", " + pot.secondary;
            } else {
                itemListStr = pot.herbGrimy + "/" + pot.herbClean + ", Vial of water";
            }
        } else {
            itemListStr = step.getBankHighlightItems();
        }

        List<List<String>> groups = bankItemManager.parseItemList(itemListStr);
        if (groups.isEmpty()) return null;

        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String itemName = itemManager.getItemComposition(item.getItemId()).getName();
            if (itemName == null) continue;

            boolean isRequired = false;
            boolean isMissing = false;

            for (List<String> group : groups) {
                for (String alt : group) {
                    String altName = bankItemManager.parseItemName(alt);
                    if (itemName.equalsIgnoreCase(altName)) {
                        isRequired = true;
                        // Check if INVENTORY has enough, not bank
                        long required = bankItemManager.parseQuantityValue(alt);
                        net.runelite.api.ItemContainer inv =
                            client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
                        long inInventory = 0;
                        if (inv != null) {
                            for (net.runelite.api.Item invItem : inv.getItems()) {
                                if (invItem.getId() <= 0) continue;
                                String invName = itemManager.getItemComposition(invItem.getId()).getName();
                                if (invName != null && invName.equalsIgnoreCase(altName)) {
                                    inInventory += invItem.getQuantity();
                                }
                            }
                        }
                        isMissing = inInventory < required;
                        break;
                    }
                }
                if (isRequired) break;
            }

            if (isRequired) {
                Rectangle bounds = new Rectangle(
                    item.getCanvasLocation().getX(),
                    item.getCanvasLocation().getY(),
                    item.getWidth(),
                    item.getHeight()
                );
                // Green if already have it, orange if still need it
                Color highlight = isMissing
                    ? new Color(255, 140, 0, 120)
                    : new Color(0, 255, 0, 80);
                Color border = isMissing
                    ? new Color(255, 140, 0, 220)
                    : new Color(0, 255, 0, 200);

                graphics.setColor(highlight);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                graphics.setColor(border);
                graphics.setStroke(new BasicStroke(2));
                graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }

        return null;
    }

    private boolean bankHasItem(Widget[] items, String name) {
        if (name == null) return false;
        for (Widget item : items) {
            if (item == null || item.isHidden() || item.getItemId() <= 0) continue;
            String n = itemManager.getItemComposition(item.getItemId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }

    private boolean inventoryHasItem(String name) {
        if (name == null) return false;
        net.runelite.api.ItemContainer inv =
            client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null) return false;
        for (net.runelite.api.Item invItem : inv.getItems()) {
            if (invItem.getId() <= 0) continue;
            String n = itemManager.getItemComposition(invItem.getId()).getName();
            if (n != null && n.equalsIgnoreCase(name)) return true;
        }
        return false;
    }
}

package com.routeplanner.bank;

import com.routeplanner.RoutePlannerPlugin;
import com.routeplanner.model.RouteStep;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Highlights matching ground items on tiles for an ITEM step in PICKUP mode.
 */
@Slf4j
@Singleton
public class GroundItemOverlay extends Overlay {

    private final Client client;
    private final RoutePlannerPlugin plugin;
    private final BankItemManager bankItemManager;
    private final ItemManager itemManager;

    @Inject
    public GroundItemOverlay(Client client, RoutePlannerPlugin plugin,
                             BankItemManager bankItemManager, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.bankItemManager = bankItemManager;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.getActiveRoute() == null) return null;
        RouteStep step = plugin.getActiveRoute().getActiveStep();
        if (step == null || !step.hasItems()) return null;
        if (!"PICKUP".equals(step.getItemMode())) return null;

        // Collect target item names (lowercased), supporting "/" alternatives
        List<List<String>> groups = bankItemManager.parseItemList(step.getItemList());
        if (groups.isEmpty()) return null;
        Set<String> targets = new HashSet<>();
        for (List<String> group : groups) {
            for (String alt : group) {
                String n = bankItemManager.parseItemName(alt);
                if (n != null) targets.add(n.toLowerCase());
            }
        }
        if (targets.isEmpty()) return null;

        Scene scene = client.getScene();
        if (scene == null) return null;
        Tile[][][] tiles = scene.getTiles();
        int z = client.getPlane();
        if (z < 0 || z >= tiles.length) return null;
        Tile[][] plane = tiles[z];

        for (Tile[] row : plane) {
            if (row == null) continue;
            for (Tile tile : row) {
                if (tile == null) continue;
                List<TileItem> groundItems = tile.getGroundItems();
                if (groundItems == null || groundItems.isEmpty()) continue;

                String matchName = null;
                for (TileItem gi : groundItems) {
                    if (gi == null) continue;
                    String name = itemManager.getItemComposition(gi.getId()).getName();
                    if (name != null && targets.contains(name.toLowerCase())) {
                        matchName = name;
                        break;
                    }
                }
                if (matchName == null) continue;

                LocalPoint lp = tile.getLocalLocation();
                if (lp == null) continue;

                net.runelite.api.ItemLayer itemLayer = tile.getItemLayer();
                if (itemLayer != null) {
                    Shape clickbox = itemLayer.getClickbox();
                    if (clickbox != null) {
                        graphics.setColor(new Color(255, 140, 0, 70));
                        graphics.fill(clickbox);
                        graphics.setColor(new Color(255, 140, 0, 230));
                        graphics.setStroke(new BasicStroke(2));
                        graphics.draw(clickbox);
                    }
                }

                net.runelite.api.Point textLoc =
                    Perspective.getCanvasTextLocation(client, graphics, lp, matchName, 0);
                if (textLoc != null) {
                    graphics.setColor(Color.BLACK);
                    graphics.drawString(matchName, textLoc.getX() + 1, textLoc.getY() + 1);
                    graphics.setColor(new Color(255, 200, 0));
                    graphics.drawString(matchName, textLoc.getX(), textLoc.getY());
                }
            }
        }
        return null;
    }

}

package com.routeplanner.bank;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

@Slf4j
@Singleton
public class BankItemManager {

    @Inject private Client client;
    @Inject private ItemManager itemManager;

    // Parse a quantity prefix like "1k", "1m", "1mil", "500k", "2.5m" from item name
    // Returns [quantity, itemName] or [1, fullString] if no quantity found
    private long suffixMultiply(double num, String suffix) {
        if (suffix == null) return (long) num;
        switch (suffix.toLowerCase()) {
            case "k": return (long)(num * 1_000);
            case "m": case "mil": return (long)(num * 1_000_000);
            case "b": return (long)(num * 1_000_000_000);
            default: return (long) num;
        }
    }

    public String parseItemName(String input) {
        input = input.trim();
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("^[\\d.]+\\s*(?:k|m|mil|b)?\\s+(.+)$", java.util.regex.Pattern.CASE_INSENSITIVE)
            .matcher(input);
        if (m.matches()) return m.group(1).trim();
        return input;
    }

    public long parseQuantityValue(String input) {
        input = input.trim();
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("^([\\d.]+)\\s*(k|m|mil|b)?\\s+.+$", java.util.regex.Pattern.CASE_INSENSITIVE)
            .matcher(input);
        if (m.matches()) {
            try {
                double num = Double.parseDouble(m.group(1));
                String suffix = m.group(2) == null ? "" : m.group(2).toLowerCase();
                return suffixMultiply(num, suffix);
            } catch (Exception ignored) {}
        }
        return 1;
    }

    // Parse item list string into groups (each group is a list of alternatives)
    // e.g. "Spade,1mil Coins/Platinum token" ->
    //      [["Spade"], ["1mil Coins", "Platinum token"]]
    public List<List<String>> parseItemList(String itemListStr) {
        if (itemListStr == null || itemListStr.trim().isEmpty()) return Collections.emptyList();
        List<List<String>> groups = new ArrayList<>();
        for (String group : itemListStr.split(",")) {
            group = group.trim();
            if (group.isEmpty()) continue;
            List<String> alternatives = new ArrayList<>();
            for (String alt : group.split("/")) {
                alt = alt.trim();
                if (!alt.isEmpty()) alternatives.add(alt);
            }
            if (!alternatives.isEmpty()) groups.add(alternatives);
        }
        return groups;
    }

    // Check if player has all required items in inventory with quantity
    public boolean hasAllItems(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return false;

        // Build map of item name -> total quantity in inventory
        Map<String, Long> inventoryQtys = new HashMap<>();
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) {
                inventoryQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
            }
        }

        for (List<String> group : groups) {
            boolean groupSatisfied = false;
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long have = inventoryQtys.getOrDefault(itemName, 0L);
                if (have >= required) {
                    groupSatisfied = true;
                    break;
                }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    // Current inventory quantities (item name lowercased -> total qty across stacks)
    private Map<String, Long> inventoryQtyMap() {
        Map<String, Long> qtys = new HashMap<>();
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return qtys;
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) qtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
        }
        return qtys;
    }

    // PICKUP: snapshot current counts of every item referenced in the list (baseline at step start)

    // PICKUP: true once enough of each group's item has been gained since the baseline

    // PICKUP: how many gained so far (summed across groups, best alternative each) -- for HUD

    // PICKUP: total required across groups (largest alternative each) -- for HUD
    public long pickupRequired(String itemListStr) {
        long total = 0;
        for (List<String> group : parseItemList(itemListStr)) {
            long req = 0;
            for (String alt : group) req = Math.max(req, parseQuantityValue(alt));
            total += req;
        }
        return total;
    }

    /** Snapshot current inventory counts for items referenced in itemListStr. */
    public java.util.Map<String, Long> snapshotInventory(String itemListStr) {
        java.util.Map<String, Long> snapshot = new java.util.HashMap<>();
        net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null || itemListStr == null) return snapshot;
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                long count = 0;
                for (net.runelite.api.Item item : inv.getItems()) {
                    if (item.getId() <= 0) continue;
                    String n = itemManager.getItemComposition(item.getId()).getName();
                    if (n != null && n.toLowerCase().equals(name)) count += item.getQuantity();
                }
                snapshot.put(name, count);
            }
        }
        return snapshot;
    }

    /** True when enough of each item group has been gained ABOVE the baseline snapshot. */
    public boolean hasAllItemsAboveBaseline(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return hasAllItems(itemListStr);
        net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.InventoryID.INVENTORY);
        if (inv == null) return false;
        // Count current inventory
        java.util.Map<String, Long> current = new java.util.HashMap<>();
        for (net.runelite.api.Item item : inv.getItems()) {
            if (item.getId() <= 0) continue;
            String n = itemManager.getItemComposition(item.getId()).getName();
            if (n == null) continue;
            current.merge(n.toLowerCase(), (long) item.getQuantity(), Long::sum);
        }
        for (java.util.List<String> group : parseItemList(itemListStr)) {
            long required = 0;
            for (String alt : group) required = Math.max(required, parseQuantityValue(alt));
            // Check if any alternative in the group satisfies the required amount above baseline
            boolean groupSatisfied = false;
            for (String alt : group) {
                String name = parseItemName(alt).toLowerCase();
                long base = baseline.getOrDefault(name, 0L);
                long gained = Math.max(0, current.getOrDefault(name, 0L) - base);
                if (gained >= required) { groupSatisfied = true; break; }
            }
            if (!groupSatisfied) return false;
        }
        return true;
    }

    // SELL: returns true when none of the listed items remain in the inventory (all sold)
    public boolean hasSoldAll(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        if (groups.isEmpty()) return true;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null) return true;

        Set<String> invNames = new HashSet<>();
        for (Item item : inventory.getItems()) {
            if (item.getId() <= 0) continue;
            String name = itemManager.getItemComposition(item.getId()).getName();
            if (name != null) invNames.add(name.toLowerCase());
        }

        for (List<String> group : groups) {
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                if (invNames.contains(itemName)) return false; // still holding one
            }
        }
        return true;
    }

    // SELL: returns [displayText, status] where status is "SOLD" or "HOLDING"
    public List<String[]> getSellStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Set<String> invNames = new HashSet<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) invNames.add(name.toLowerCase());
            }
        }

        for (List<String> group : groups) {
            boolean holding = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                if (invNames.contains(parseItemName(alt).toLowerCase())) holding = true;
            }
            result.add(new String[]{disp.toString(), holding ? "HOLDING" : "SOLD"});
        }
        return result;
    }

    // Returns list of [displayText, status] where status is "HAVE" or "NEED"
    // Used by the HUD to show the item checklist on screen.
    public List<String[]> getItemStatusList(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> invQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) {
                    invQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
                }
            }
        }

        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                if (invQtys.getOrDefault(itemName, 0L) >= required) {
                    have = true;
                }
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    /** Same as getItemStatusList but subtracts baseline counts for PICKUP steps. */
    public List<String[]> getItemStatusList(String itemListStr, java.util.Map<String, Long> baseline) {
        if (baseline == null) return getItemStatusList(itemListStr);
        List<List<String>> groups = parseItemList(itemListStr);
        List<String[]> result = new ArrayList<>();
        if (groups.isEmpty()) return result;
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> invQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) invQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
            }
        }
        for (List<String> group : groups) {
            boolean have = false;
            StringBuilder disp = new StringBuilder();
            for (int i = 0; i < group.size(); i++) {
                String alt = group.get(i);
                if (i > 0) disp.append("/");
                disp.append(alt);
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long base = baseline.getOrDefault(itemName, 0L);
                long gained = Math.max(0, invQtys.getOrDefault(itemName, 0L) - base);
                if (gained >= required) have = true;
            }
            result.add(new String[]{disp.toString(), have ? "HAVE" : "NEED"});
        }
        return result;
    }

    // Get list of missing items with quantities
    public List<String> getMissingItems(String itemListStr) {
        List<List<String>> groups = parseItemList(itemListStr);
        List<String> missing = new ArrayList<>();
        if (groups.isEmpty()) return missing;

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        Map<String, Long> inventoryQtys = new HashMap<>();
        if (inventory != null) {
            for (Item item : inventory.getItems()) {
                if (item.getId() <= 0) continue;
                String name = itemManager.getItemComposition(item.getId()).getName();
                if (name != null) {
                    inventoryQtys.merge(name.toLowerCase(), (long) item.getQuantity(), Long::sum);
                }
            }
        }

        for (List<String> group : groups) {
            boolean found = false;
            for (String alt : group) {
                String itemName = parseItemName(alt).toLowerCase();
                long required = parseQuantityValue(alt);
                long have = inventoryQtys.getOrDefault(itemName, 0L);
                if (have >= required) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                missing.add(String.join("/", group));
            }
        }
        return missing;
    }
}

package com.routeplanner;

import java.io.IOException;
import java.io.InputStream;
import java.util.BitSet;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Reads collision-map.zip using the exact same format as Runemoro/shortest-path FlagMap.
 *
 * Index formula (from FlagMap.java decompilation):
 *   index = (plane * 64 * 64 + (y - minY) * 64 + (x - minX)) * 2 + direction
 *
 * Directions: 0 = can travel NORTH from tile, 1 = can travel EAST from tile
 * South is stored as North of the tile below. West is stored as East of the tile to the left.
 * A set bit means movement IS ALLOWED (not blocked).
 */
public class WorldCollisionMap {

    public static final int NORTH = 0;
    public static final int EAST  = 1;

    private static final int REGION_SIZE = 64;

    private static class RegionData {
        final int minX;
        final int minY;
        final BitSet flags;
        final byte planeCount;

        RegionData(int minX, int minY, byte[] data) {
            this.minX = minX;
            this.minY = minY;
            this.flags = BitSet.valueOf(data);
            // planeCount = ceil(flags.size() / 8192)
            int size = flags.size();
            this.planeCount = (byte) ((size + 8192 - 1) / 8192);
        }

        boolean get(int x, int y, int plane, int direction) {
            if (x < minX || x >= minX + REGION_SIZE) return false;
            if (y < minY || y >= minY + REGION_SIZE) return false;
            if (plane < 0 || planeCount <= 0) return false;
            if (direction < 0 || direction >= 2) return false;
            int idx = (plane * REGION_SIZE * REGION_SIZE
                + (y - minY) * REGION_SIZE
                + (x - minX)) * 2 + direction;
            return flags.get(idx);
        }
    }

    // key = regionX | (regionY << 16)
    private final Map<Integer, RegionData> regions = new HashMap<>();

    public WorldCollisionMap(InputStream zipStream) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(zipStream)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                String[] parts = entry.getName().split("_");
                int regionX = Integer.parseInt(parts[0]);
                int regionY = Integer.parseInt(parts[1]);
                int key = regionX | (regionY << 16);
                int minX = regionX * REGION_SIZE;
                int minY = regionY * REGION_SIZE;
                byte[] data = zis.readAllBytes();
                regions.put(key, new RegionData(minX, minY, data));
                zis.closeEntry();
            }
        }
    }

    /**
     * Returns true if movement NORTH from (x,y,plane) is allowed.
     */
    public boolean canMoveNorth(int x, int y, int plane) {
        return getFlag(x, y, plane, NORTH);
    }

    /**
     * Returns true if movement SOUTH from (x,y,plane) is allowed.
     * South from (x,y) = North from (x, y-1).
     */
    public boolean canMoveSouth(int x, int y, int plane) {
        return getFlag(x, y - 1, plane, NORTH);
    }

    /**
     * Returns true if movement EAST from (x,y,plane) is allowed.
     */
    public boolean canMoveEast(int x, int y, int plane) {
        return getFlag(x, y, plane, EAST);
    }

    /**
     * Returns true if movement WEST from (x,y,plane) is allowed.
     * West from (x,y) = East from (x-1, y).
     */
    public boolean canMoveWest(int x, int y, int plane) {
        return getFlag(x - 1, y, plane, EAST);
    }

    private boolean getFlag(int x, int y, int plane, int direction) {
        int regionX = x / REGION_SIZE;
        int regionY = y / REGION_SIZE;
        int key = regionX | (regionY << 16);
        RegionData region = regions.get(key);
        if (region == null) return true; // unknown = assume walkable
        return region.get(x, y, plane, direction);
    }

    public boolean isLoaded() {
        return !regions.isEmpty();
    }
}

